/* HtmlForgeX scrolling navigation. Keep each observer within its owning control. */
(function () {
    function initialize() {
        if (typeof IntersectionObserver === "undefined") return;
        document.querySelectorAll(".sectionScrolling").forEach(function (root) {
            var links = new Map();
            root.querySelectorAll('.section-nav a[href^="#"]').forEach(function (link) {
                if (link.closest(".sectionScrolling") === root) {
                    links.set(link.getAttribute("href").slice(1), link);
                }
            });
            var targets = new Map();
            root.querySelectorAll("section[id]").forEach(function (section) {
                var link = links.get(section.id);
                if (section.closest(".sectionScrolling") === root && link) {
                    targets.set(section, link.closest("li"));
                }
            });
            if (!targets.size) return;
            var observer = new IntersectionObserver(function (entries) {
                entries.forEach(function (entry) {
                    var item = targets.get(entry.target);
                    if (item) item.classList.toggle("active", entry.intersectionRatio > 0);
                });
            });
            targets.forEach(function (_, section) { observer.observe(section); });
        });
    }
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initialize, { once: true });
    } else {
        initialize();
    }
})();
